$roots = @("$HOME\Desktop\DEV", "$HOME\Desktop\DEV\Football", "$HOME\Desktop\DEV\SpecialRequests")
$repos = @("$HOME\Desktop\DEV") + ($roots | ForEach-Object { Get-ChildItem $_ -Directory -ErrorAction SilentlyContinue } | Where-Object { Test-Path "$($_.FullName)\.git" } | ForEach-Object FullName)
$repos += "$HOME\.claude", "$HOME\.claude\skills", "$HOME\.claude\global-memory"
foreach ($r in $repos | Select-Object -Unique) {
  $d = (git -C $r status --porcelain 2>$null | Measure-Object).Count
  $sb = git -C $r status -sb 2>$null | Select-Object -First 1
  if ($d -gt 0 -or $sb -match 'ahead') { "{0} | dirty={1} | {2}" -f $r.Replace("$HOME\",''), $d, $sb }
}
"--- errors.log:"; Get-Content "$HOME\.claude\global-memory\transcripts\.errors.log" -ErrorAction SilentlyContinue | Select-Object -Last 10
"--- today transcript:"; Get-Item "$HOME\.claude\global-memory\transcripts\2026-10-02.md" -ErrorAction SilentlyContinue | Select Name, LastWriteTime

